public static List<PathSegmentImpl> getPathSegments(String path) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    int length = path.length();
    if (!path.isEmpty()) {
        if (path.startsWith("/")) {
            // Ignore leading slash
            path = path.substring(1);
            length -= 1;
        }
        if (length > 0) {
            boolean prevDelimiter = false;
            char prevChar;
            int startIndex = 0;
            for (int i = 0; i < length; i++) {
                char c = path.charAt(i);
                if (c == '/') {
                    if (!prevDelimiter) {
                        startIndex = i;
                    }
                    prevDelimiter = true;
                } else {
                    prevDelimiter = false;
                }
                if (i == length - 1) {
                    segments.add(new PathSegmentImpl(path.substring(startIndex, i + 1)));
