        for (Vertex neighbor : graph.neighbors(edge)) {
            if (neighbor.index > edge.to.index) {
                separator.add(new Pair<>(edge.to.index, neighbor.index));
            }
        }
        separatorList.add(new Pair<>(separator, edge));
    }

    List<Integer> globalSeparator = new ArrayList<>();
    for (Pair<List<Pair<Integer, Integer>>, E> entry : separatorList) {
        globalSeparator.addAll(entry.first);
    }

    Collections.sort(globalSeparator, new Comparator<Integer>() {
