public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Select the specified row in the table
    table.changeSelection(row, 0, false, false);

    // Get the visible row bounds
    Rectangle visibleRect = table.getVisibleRect();
    int firstRow = table.rowAtPoint(visibleRect.getLocation());
    int lastRow = table.rowAtPoint(new Point(visibleRect.getWidth(), visibleRect.getHeight()));

    // If the selected row is offscreen, scroll the table to make it visible
    if (row < firstRow || row > lastRow) {
        // Calculate the new scroll position
        JViewport viewport = pane.getViewport();
        int currentScroll = viewport.getViewPosition().y;
        int nextScroll = currentScroll + (row - firstRow) * table.getRowHeight();

        // Set the new scroll position and repaint the table
        viewport.setViewPosition(new Point(0, nextScroll));
        table.repaint();
    }
}

public ByteVector putInt(int intValue) {
    // Check if the buffer needs to be enlarged
    if (size() < 4) {
        // Enlarge the buffer by doubling its current size
        int newSize = 2 * size();
        if (newSize < 4) {
            newSize = 4;
        }
        grow(newSize - size());
    }

    // Write the int value to the buffer
    for (int i = 0; i < 4; i++) {
        int shift = (3 - i) * 8;
        byte value = (byte) ((intValue >> shift) & 0xFF);
        add(value);
    }

    return this;
}

